"""
Drafts Changelogs/Version <VERSION>.md for a merged pull request using the Anthropic API.
VERSION is read from Launcher/MapDesc.cs. If the file already exists it is passed back in
as the current draft, so manual edits are kept and new changes get merged in.
"""
import glob
import json
import os
import re
import subprocess
import sys
import urllib.error
import urllib.request

MODEL = "claude-sonnet-5-5"
MAX_DIFF_CHARS = 120_000
STYLE_EXAMPLES = 3  # most recent existing changelogs used as style examples


def run(*args):
    return subprocess.run(args, check=True, capture_output=True, text=True, encoding="utf-8").stdout


def read_version():
    text = open("Launcher/MapDesc.cs", encoding="utf-8-sig").read()
    m = re.search(r'VERSION\s*=\s*"([^"]+)"', text)
    if not m:
        sys.exit("Could not find VERSION in Launcher/MapDesc.cs")
    return m.group(1)


def version_key(path):
    m = re.search(r"Version (\d+(?:\.\d+)*)", path)
    return tuple(int(p) for p in m.group(1).split(".")) if m else (0,)


def main():
    key = os.environ.get("ANTHROPIC_API_KEY")
    if not key:
        sys.exit("ANTHROPIC_API_KEY secret is not set (Settings > Secrets and variables > Actions).")

    base = os.environ["BASE_SHA"]
    head = os.environ["HEAD_SHA"]
    version = read_version()
    out_path = f"Changelogs/Version {version}.md"

    commits = run("git", "log", "--no-merges", "--format=- %s%n%b", f"{base}..{head}").strip()
    # Source code only: skip the map binaries, build output, generated artifacts and changelogs themselves.
    diff = run(
        "git", "diff", f"{base}...{head}", "--", "Source", "Launcher/MapDesc.cs",
        ":(exclude)Source/bin", ":(exclude)Source/obj", ":(exclude)Source/AutoGenerated",
    )
    if len(diff) > MAX_DIFF_CHARS:
        diff = diff[:MAX_DIFF_CHARS] + "\n...[diff truncated]"
    if not commits and not diff.strip():
        print("No source changes; nothing to write.")
        return

    examples = sorted(glob.glob("Changelogs/Version *.md"), key=version_key)
    examples = [p for p in examples if p != out_path][-STYLE_EXAMPLES:]
    example_text = "\n\n".join(
        f"=== {os.path.basename(p)} ===\n{open(p, encoding='utf-8-sig').read().strip()}" for p in examples
    )
    existing = ""
    if os.path.exists(out_path):
        existing = open(out_path, encoding="utf-8-sig").read().strip()

    system = (
        "You write player-facing patch notes for Run Kitty Run, a Warcraft 3 map, in Discord markdown. "
        "Match the structure and tone of the example changelogs: a bold-underlined title line "
        "'**__Run Kitty Run - Remastered v<VERSION>__**' (keep any suffix like ASYNC that the examples/existing draft use), "
        "then sections headed '**__Section__**' with '- ' bullets. Only describe changes players or admins would notice "
        "(gameplay, commands, rewards, UI, bug fixes); skip pure refactors, memory/leak cleanups and internal renames "
        "unless they fix something visible. Use backticks for commands like `-async`. Be concise and plain. "
        "Do not invent changes that are not in the diff or commits. "
        "Output ONLY the changelog text, no preamble and no code fences."
    )
    user = (
        f"Version: {version}\n\nPR title: {os.environ.get('PR_TITLE', '')}\n"
        f"PR description:\n{os.environ.get('PR_BODY') or '(none)'}\n\n"
        f"Commits in this PR:\n{commits}\n\n"
        f"Source diff:\n{diff}\n\n"
        f"Example changelogs for style:\n{example_text}\n\n"
    )
    if existing:
        user += (
            "A draft for this version already exists. Keep its wording and any manual edits, and merge in "
            f"anything from this PR that it is missing:\n=== current draft ===\n{existing}\n"
        )

    body = json.dumps({
        "model": MODEL,
        "max_tokens": 2000,
        "system": system,
        "messages": [{"role": "user", "content": user}],
    }).encode("utf-8")
    req = urllib.request.Request(
        "https://api.anthropic.com/v1/messages",
        data=body,
        headers={"x-api-key": key, "anthropic-version": "2023-06-01", "content-type": "application/json"},
    )
    try:
        with urllib.request.urlopen(req, timeout=120) as resp:
            data = json.load(resp)
    except urllib.error.HTTPError as e:
        sys.exit(f"Anthropic API error {e.code}: {e.read().decode('utf-8', 'replace')}")

    text = "".join(b.get("text", "") for b in data.get("content", []) if b.get("type") == "text").strip()
    if not text:
        sys.exit("Empty response from API.")

    os.makedirs("Changelogs", exist_ok=True)
    with open(out_path, "w", encoding="utf-8", newline="") as f:
        f.write(text.replace("\r\n", "\n") + "\n")
    print(f"Wrote {out_path}")


if __name__ == "__main__":
    main()
